  "official/c53569894.lua":"--光のピラミッド\n--Pyramid of Light\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\tc:RegisterEffect(e1)\n\t--Register when this card leaves the field\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetType(EFFECT_TYPE_CONTINUOUS+EFFECT_TYPE_SINGLE)\n\te2:SetProperty(EFFECT_FLAG_CANNOT_DISABLE)\n\te2:SetCode(EVENT_LEAVE_FIELD_P)\n\te2:SetOperation(s.checkop)\n\tc:RegisterEffect(e2)\n\t--Destroy and banish \"Andro Sphinx\" and \"Sphinx Teleia you control\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetCategory(CATEGORY_DESTROY+CATEGORY_REMOVE)\n\te3:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_CONTINUOUS)\n\te3:SetCode(EVENT_LEAVE_FIELD)\n\te3:SetOperation(s.desop)\n\te3:SetLabelObject(e2)\n\tc:RegisterEffect(e3)\nend\ns.listed_names={15013468,51402177} --\"Andro Sphinx\",\"Sphinx Teleia\nfunction s.checkop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif c:IsFaceup() and not c:IsDisabled() then\n\t\te:SetLabel(1)\n\telse\n\t\te:SetLabel(0)\n\tend\nend\nfunction s.desop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif e:GetLabelObject():GetLabel()==1 and c:IsPreviousControler(tp) then\n\t\tlocal g=Duel.GetMatchingGroup(aux.FaceupFilter(Card.IsCode,15013468,51402177),tp,LOCATION_ONFIELD,0,nil)\n\t\tif #g>0 then\n\t\t\tDuel.Hint(HINT_CARD,1-tp,id)\n\t\t\tDuel.Destroy(g,REASON_EFFECT,LOCATION_REMOVED)\n\t\tend\n\tend\nend",
  "c53569894.lua":"--光のピラミッド\n--Pyramid of Light\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\tc:RegisterEffect(e1)\n\t--Register when this card leaves the field\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetType(EFFECT_TYPE_CONTINUOUS+EFFECT_TYPE_SINGLE)\n\te2:SetProperty(EFFECT_FLAG_CANNOT_DISABLE)\n\te2:SetCode(EVENT_LEAVE_FIELD_P)\n\te2:SetOperation(s.checkop)\n\tc:RegisterEffect(e2)\n\t--Destroy and banish \"Andro Sphinx\" and \"Sphinx Teleia you control\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetCategory(CATEGORY_DESTROY+CATEGORY_REMOVE)\n\te3:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_CONTINUOUS)\n\te3:SetCode(EVENT_LEAVE_FIELD)\n\te3:SetOperation(s.desop)\n\te3:SetLabelObject(e2)\n\tc:RegisterEffect(e3)\nend\ns.listed_names={15013468,51402177} --\"Andro Sphinx\",\"Sphinx Teleia\nfunction s.checkop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif c:IsFaceup() and not c:IsDisabled() then\n\t\te:SetLabel(1)\n\telse\n\t\te:SetLabel(0)\n\tend\nend\nfunction s.desop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif e:GetLabelObject():GetLabel()==1 and c:IsPreviousControler(tp) then\n\t\tlocal g=Duel.GetMatchingGroup(aux.FaceupFilter(Card.IsCode,15013468,51402177),tp,LOCATION_ONFIELD,0,nil)\n\t\tif #g>0 then\n\t\t\tDuel.Hint(HINT_CARD,1-tp,id)\n\t\t\tDuel.Destroy(g,REASON_EFFECT,LOCATION_REMOVED)\n\t\tend\n\tend\nend",
  "official/c53582587.lua":"--激流葬\n--Torrential Tribute\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate(summon)\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetCategory(CATEGORY_DESTROY)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_SUMMON_SUCCESS)\n\te1:SetTarget(s.target)\n\te1:SetOperation(s.activate)\n\tc:RegisterEffect(e1)\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetCategory(CATEGORY_DESTROY)\n\te2:SetType(EFFECT_TYPE_ACTIVATE)\n\te2:SetCode(EVENT_FLIP_SUMMON_SUCCESS)\n\te2:SetTarget(s.target)\n\te2:SetOperation(s.activate)\n\tc:RegisterEffect(e2)\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetCategory(CATEGORY_DESTROY)\n\te3:SetType(EFFECT_TYPE_ACTIVATE)\n\te3:SetCode(EVENT_SPSUMMON_SUCCESS)\n\te3:SetTarget(s.target)\n\te3:SetOperation(s.activate)\n\tc:RegisterEffect(e3)\nend\nfunction s.target(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return Duel.IsExistingMatchingCard(aux.TRUE,tp,LOCATION_MZONE,LOCATION_MZONE,1,nil) end\n\tlocal g=Duel.GetMatchingGroup(aux.TRUE,tp,LOCATION_MZONE,LOCATION_MZONE,nil)\n\tDuel.SetOperationInfo(0,CATEGORY_DESTROY,g,#g,0,0)\nend\nfunction s.activate(e,tp,eg,ep,ev,re,r,rp)\n\tlocal g=Duel.GetMatchingGroup(aux.TRUE,tp,LOCATION_MZONE,LOCATION_MZONE,nil)\n\tif #g>0 then\n\t\tDuel.Destroy(g,REASON_EFFECT)\n\tend\nend",
